insert into orgs (id, slug, name, ein, website, mission, what_gifts_fund, status, org_type) values
  ('00000000-0000-4000-a000-000000000007', 'second-chance-paws', 'Second Chance Paws', '00-0000007', 'https://example.org/second-chance-paws', 'A volunteer-run shelter giving overlooked dogs and cats time, training and a second chance at a home.', '$35 vaccinates a new arrival. $150 covers a month of care for a senior dog.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000008', 'rooted-neighborhoods', 'Rooted Neighborhoods', '00-0000008', 'https://example.org/rooted-neighborhoods', 'Planting and caring for street trees on the blocks with the least shade, with the neighbors who live there.', '$60 plants one street tree with a stake, mulch and two years of watering.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000009', 'westside-arts-studio', 'Westside Arts Studio', '00-0000009', 'https://example.org/westside-arts-studio', 'Free art classes and public murals made with teens from the west side.', '$25 stocks a student''s sketchbook kit for a semester. $1,200 funds a mural wall.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000010', 'northside-youth-soccer', 'Northside Youth Soccer', '00-0000010', 'https://example.org/northside-youth-soccer', 'No-fee soccer for kids 6 to 14, with volunteer coaches and a ride home when needed.', '$45 covers a player''s cleats and shin guards. $400 covers a season of field rental.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000011', 'bridge-welcome-center', 'Bridge Welcome Center', '00-0000011', 'https://example.org/bridge-welcome-center', 'Helping newly arrived families settle in: English classes, school enrollment, first apartments and jobs.', '$80 buys a welcome kit for a family''s first week. $300 covers a month of English classes for one adult.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000012', 'clear-minds-collective', 'Clear Minds Collective', '00-0000012', 'https://example.org/clear-minds-collective', 'Free peer support groups and a warm line staffed by trained volunteers who have been there.', '$20 trains a volunteer for one hour. $500 keeps the warm line open for a week of evenings.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000013', 'open-shelves', 'Open Shelves', '00-0000013', 'https://example.org/open-shelves', 'Little libraries in laundromats, clinics and bus shelters, restocked every week by volunteers.', '$15 fills a shelf with ten books. $250 builds and installs a new little library.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000014', 'neighborhood-health-corps', 'Neighborhood Health Corps', '00-0000014', 'https://example.org/neighborhood-health-corps', 'Volunteer nurses and community health workers running free screening nights and helping people find a doctor.', '$40 covers supplies for one screening night station. $2,000 funds a month of follow-up calls.', 'verified', 'nonprofit'),
  ('00000000-0000-4000-a000-000000000015', 'meridian-health-foundation', 'Meridian Health Foundation', '00-0000015', 'https://example.org/meridian-health-foundation', 'A private foundation funding community health and mental health care close to home.', 'Grants to local clinics and peer programs, most between $10,000 and $50,000.', 'verified', 'foundation');
