insert into posts (org_id, kind, body, image_paths, image_alts, image_credits, beneficiary_consent, created_at) values
  ('00000000-0000-4000-a000-000000000007', 'impact_story', 'Biscuit spent 214 days with us. On Sunday she went home with a retired teacher who reads to her on the porch. Thank you to every walker who never skipped her.', array['00000000-0000-4000-a000-000000000007/volunteer-golden.jpg']::text[], array['A volunteer crouching to greet a golden retriever at the shelter']::text[], array['U.S. Navy photo by Petty Officer 2nd Class Kelly M Agee, public domain, via Wikimedia Commons']::text[], true, now() - interval '77 hours'),
  ('00000000-0000-4000-a000-000000000007', 'update', 'Saturday adoption day: 11 dogs and 6 cats found homes. Our volunteers logged 140 walking hours this month.', array['00000000-0000-4000-a000-000000000007/volunteer-two-dogs.jpg']::text[], array['A volunteer sitting on the ground hugging two shelter dogs']::text[], array['U.S. Navy photo by Petty Officer 2nd Class Kelly M Agee, public domain, via Wikimedia Commons']::text[], true, now() - interval '216 hours'),
  ('00000000-0000-4000-a000-000000000007', 'ask', 'We need 20 more weekday dog walkers, especially mornings. One hour a week makes a real difference for a shelter dog.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '408 hours'),
  ('00000000-0000-4000-a000-000000000007', 'update', 'New kennel heaters are in before the first cold night. Thank you, neighbors, for the donation drive.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '792 hours'),
  ('00000000-0000-4000-a000-000000000008', 'impact_story', 'Delmar Street has shade for the first time in decades: 46 new trees, planted by 60 neighbors in one morning.', array['00000000-0000-4000-a000-000000000008/planting-saplings.jpg']::text[], array['Volunteers kneeling to plant saplings in a field']::text[], array['Christian Anold Mosha, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '62 hours'),
  ('00000000-0000-4000-a000-000000000008', 'update', 'Watering crews are out every Tuesday and Thursday through October. Young trees need about 15 gallons a week.', array['00000000-0000-4000-a000-000000000008/carrying-trees.jpg']::text[], array['A volunteer carrying young trees in bags along a trail']::text[], array['USFWS/Southeast, public domain, via Wikimedia Commons']::text[], true, now() - interval '288 hours'),
  ('00000000-0000-4000-a000-000000000008', 'update', 'Our two-year survival rate is 88%, up from 71%. The difference: neighbors who adopt a tree and water it.', array['00000000-0000-4000-a000-000000000008/planting-hillside.jpg']::text[], array['Volunteers in safety vests planting on a dry hillside']::text[], array['Joshua Tree National Park, public domain, via Wikimedia Commons']::text[], true, now() - interval '624 hours'),
  ('00000000-0000-4000-a000-000000000008', 'ask', 'Know a block that bakes in summer? Nominate it for spring planting. Residents choose the species.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '984 hours'),
  ('00000000-0000-4000-a000-000000000009', 'update', 'Mural walk: our teens studied this tunnel mural before sketching their own wall for the underpass. Next step: a community vote on designs.', array['00000000-0000-4000-a000-000000000009/tunnel-mural.jpg']::text[], array['A colorful community mural painted along a tunnel wall']::text[], array['University of Malta Department of Arts, Open Communities and Adult..., CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '108 hours'),
  ('00000000-0000-4000-a000-000000000009', 'update', 'Guest artist week: muralist Lena Ortiz showed students how to scale a sketch to a 30-foot wall.', array['00000000-0000-4000-a000-000000000009/wall-painting.jpg']::text[], array['An artist in orange overalls painting a large black animal on a white wall']::text[], array['Антон Хлабов, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '360 hours'),
  ('00000000-0000-4000-a000-000000000009', 'update', 'Fall classes are full, with 84 students. We added a Thursday evening session for the waitlist.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '696 hours'),
  ('00000000-0000-4000-a000-000000000009', 'ask', 'We are out of acrylics and brushes. A $25 kit keeps one student painting all semester.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '1248 hours'),
  ('00000000-0000-4000-a000-000000000010', 'impact_story', 'Our U12 team finished the season undefeated, but the real win: every player showed up to every practice, thanks to the volunteer carpool.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '132 hours'),
  ('00000000-0000-4000-a000-000000000010', 'update', 'Registration for spring is open and free. We have room for 60 more players.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '312 hours'),
  ('00000000-0000-4000-a000-000000000010', 'update', '32 volunteer coaches finished first-aid and concussion training this weekend.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '816 hours'),
  ('00000000-0000-4000-a000-000000000010', 'ask', 'Our cleats closet is empty in sizes 3 to 6. Gently used donations welcome at Saturday practice.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '1392 hours'),
  ('00000000-0000-4000-a000-000000000011', 'impact_story', 'Amina started English class in March. Last week she led her son''s parent-teacher conference without an interpreter.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '91 hours'),
  ('00000000-0000-4000-a000-000000000011', 'update', 'Twelve families arrived this month. Volunteers set up nine apartments with beds, dishes and a full fridge before move-in.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '264 hours'),
  ('00000000-0000-4000-a000-000000000011', 'update', 'Our job readiness group helped 18 adults land first jobs this quarter, most in health care and logistics.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '648 hours'),
  ('00000000-0000-4000-a000-000000000011', 'ask', 'We need volunteer drivers for school enrollment week. Two hours, any morning, a huge help.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '1080 hours'),
  ('00000000-0000-4000-a000-000000000012', 'impact_story', 'Our warm line answered its 3,900th call this year. Most callers just need someone who listens, and has been there.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '149 hours'),
  ('00000000-0000-4000-a000-000000000012', 'update', 'New peer group on Wednesdays for new parents. Facilitated by two volunteer moms, free and confidential.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '384 hours'),
  ('00000000-0000-4000-a000-000000000012', 'update', 'Twenty-two new volunteers finished the 40-hour peer support training. They start on the warm line next week.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '912 hours'),
  ('00000000-0000-4000-a000-000000000013', 'impact_story', 'The little library at the Main Street laundromat empties every week. This week a regular left a note: "My daughter reads while we wait now."', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '118 hours'),
  ('00000000-0000-4000-a000-000000000013', 'update', 'Three new little libraries installed this month: two clinics and the Route 9 bus shelter.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '336 hours'),
  ('00000000-0000-4000-a000-000000000013', 'ask', 'Children''s picture books are our most requested and the first to go. Book drive at the library through Friday.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '744 hours'),
  ('00000000-0000-4000-a000-000000000014', 'impact_story', 'At last Thursday''s screening night, 112 neighbors had blood pressure checks. 19 were connected to a doctor the same week.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '70 hours'),
  ('00000000-0000-4000-a000-000000000014', 'update', 'Our follow-up call team reached 640 people this year who had no regular doctor. Most now do.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '456 hours'),
  ('00000000-0000-4000-a000-000000000014', 'update', 'Sixteen new community health workers finished training this week: blood pressure, diabetes screening and how to help someone find a doctor.', array['00000000-0000-4000-a000-000000000014/health-workers-class.jpg', '00000000-0000-4000-a000-000000000014/health-trainer.jpg']::text[], array['Community health workers taking notes during a training class', 'A trainer teaching a class of community health workers']::text[], array['Ness Kerson/madNESS Photography for AusAID, CC BY-SA 4.0, via Wikimedia Commons', 'Ness Kerson/madNESS Photography for AusAID, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '228 hours'),
  ('00000000-0000-4000-a000-000000000014', 'update', 'Screening nights are now monthly at the Eastside recreation center, with Spanish and Somali interpreters.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '1056 hours'),
  ('00000000-0000-4000-a000-000000000015', 'update', 'We''re funding peer-led mental health programs this year, because people often reach out first to someone who has been there.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '192 hours'),
  ('00000000-0000-4000-a000-000000000001', 'update', 'The pantry garden is done for the season: 640 pounds of produce this year, all of it on Tuesday shelves within a day of picking.', array['00000000-0000-4000-a000-000000000001/garden-hands.jpg']::text[], array['Hands working soil in a community garden bed']::text[], array['Caitlin Purdome, U.S. Forest Service, public domain, via Wikimedia Commons']::text[], true, now() - interval '504 hours'),
  ('00000000-0000-4000-a000-000000000002', 'impact_story', 'One year ago the Reyes family moved out of the shelter. This month they renewed their lease, and their son made the honor roll.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '168 hours'),
  ('00000000-0000-4000-a000-000000000002', 'ask', 'Moving day crews need two more pickup trucks on Saturday mornings. Gas cards provided.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '552 hours'),
  ('00000000-0000-4000-a000-000000000003', 'update', 'Tutor orientation is full for October. Next session: November 4. Bring a favorite children''s book.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '240 hours'),
  ('00000000-0000-4000-a000-000000000003', 'impact_story', 'Jamal read his first chapter book to his tutor, out loud, all the way through. He asked to keep it.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '864 hours'),
  ('00000000-0000-4000-a000-000000000004', 'update', 'Native seed collection day: 30 volunteers gathered seed from 14 species for next spring''s planting.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '480 hours'),
  ('00000000-0000-4000-a000-000000000004', 'ask', 'We''re short on work gloves in small sizes. Donations at the trailhead kiosk any weekend.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '1152 hours'),
  ('00000000-0000-4000-a000-000000000005', 'update', 'Our grants committee read 96 applications this cycle. Every applicant gets written feedback, funded or not.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '432 hours'),
  ('00000000-0000-4000-a000-000000000006', 'update', 'Rapid-response grants are open year round for food programs in the river valley. Most decisions in under three weeks.', '{}'::text[], '{}'::text[], '{}'::text[], false, now() - interval '600 hours');
insert into posts (org_id, kind, body, video_path, video_poster_path, video_alt, video_credit, created_at) values
  ('00000000-0000-4000-a000-000000000001', 'update', 'Saturday''s farm delivery: 1,000 pounds of potatoes, unloaded in twenty minutes and on Tuesday''s shelves.', '00000000-0000-4000-a000-000000000001/truck-delivery.webm', '00000000-0000-4000-a000-000000000001/truck-delivery.jpg', 'A worker unloading sacks of potatoes from a delivery truck', 'USDA, public domain, via Wikimedia Commons', now() - interval '122 hours'),
  ('00000000-0000-4000-a000-000000000008', 'update', 'Bed prep for spring planting: every new tree pit gets loosened soil and compost before it gets a tree.', '00000000-0000-4000-a000-000000000008/bed-prep.webm', '00000000-0000-4000-a000-000000000008/bed-prep.jpg', 'A volunteer working soil in a garden bed', 'USDA, public domain, via Wikimedia Commons', now() - interval '202 hours'),
  ('00000000-0000-4000-a000-000000000009', 'update', 'Mural walk, part two: community murals that tell a neighborhood''s story. Our teens picked their favorite details for the underpass design.', '00000000-0000-4000-a000-000000000009/mural-pan.webm', '00000000-0000-4000-a000-000000000009/mural-pan.jpg', 'A long, colorful community mural along a street', 'Luis Alvaz, CC BY-SA 4.0, via Wikimedia Commons', now() - interval '271 hours');
