insert into orgs (id, slug, name, ein, website, mission, what_gifts_fund, status, org_type, logo_url) values
  ('00000000-0000-4000-a000-000000000016', 'eastgate-food-rescue', 'Eastgate Food Rescue', '00-0000016', 'https://example.org/eastgate-food-rescue', 'Picking up surplus food from grocers and restaurants every night and getting it to pantries by morning.', '$20 rescues about 80 meals'' worth of food. $600 keeps a van on the road for a month.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000016/logo.png'),
  ('00000000-0000-4000-a000-000000000017', 'keystone-housing-collaborative', 'Keystone Housing Collaborative', '00-0000017', 'https://example.org/keystone-housing-collaborative', 'Helping renters stay housed: emergency rent help, free legal clinics and landlord mediation.', '$250 closes a typical rent gap. $1,500 keeps a family in their home through a crisis month.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000017/logo.png'),
  ('00000000-0000-4000-a000-000000000018', 'pine-street-tutoring', 'Pine Street Tutoring', '00-0000018', 'https://example.org/pine-street-tutoring', 'Free one-on-one math and reading tutoring for middle schoolers, after school, five days a week.', '$30 covers a month of tutoring materials for one student. $900 trains ten new tutors.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000018/logo.png'),
  ('00000000-0000-4000-a000-000000000019', 'blue-heron-watershed', 'Blue Heron Watershed Alliance', '00-0000019', 'https://example.org/blue-heron-watershed', 'Restoring creeks and wetlands in the Blue Heron watershed, one stream bank at a time.', '$40 buys 20 native plugs for a stream bank. $2,500 funds a season of water testing.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000019/logo.png'),
  ('00000000-0000-4000-a000-000000000020', 'lantern-literacy', 'Lantern Literacy Project', '00-0000020', 'https://example.org/lantern-literacy', 'Free adult literacy classes and one-on-one tutoring for anyone who wants to read better.', '$50 covers a learner''s books for a term. $400 trains a new volunteer tutor.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000020/logo.png'),
  ('00000000-0000-4000-a000-000000000021', 'hearth-and-home-shelter', 'Hearth & Home Shelter', '00-0000021', 'https://example.org/hearth-and-home-shelter', 'A 60-bed shelter with case managers who help each guest move into a home of their own.', '$35 provides a night of shelter, dinner and breakfast. $1,000 furnishes a first apartment.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000021/logo.png'),
  ('00000000-0000-4000-a000-000000000022', 'saltmarsh-wildlife-rescue', 'Saltmarsh Wildlife Rescue', '00-0000022', 'https://example.org/saltmarsh-wildlife-rescue', 'Rescuing, treating and releasing injured coastal birds and wildlife.', '$25 feeds a recovering heron for a week. $300 covers a rescue run and first treatment.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000022/logo.png'),
  ('00000000-0000-4000-a000-000000000023', 'southside-music-lab', 'Southside Music Lab', '00-0000023', 'https://example.org/southside-music-lab', 'Free music lessons, instruments to borrow and a recording studio for teens.', '$40 covers a month of lessons. $250 repairs and refurbishes a donated instrument.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000023/logo.png'),
  ('00000000-0000-4000-a000-000000000024', 'shared-table-kitchen', 'Shared Table Refugee Kitchen', '00-0000024', 'https://example.org/shared-table-kitchen', 'A community kitchen where newly arrived cooks train for restaurant jobs while making meals for neighbors.', '$15 provides five community meals. $500 sponsors a trainee''s food-safety certification.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000024/logo.png'),
  ('00000000-0000-4000-a000-000000000025', 'steady-path-peers', 'Steady Path Recovery Peers', '00-0000025', 'https://example.org/steady-path-peers', 'Peer recovery coaches who have been there, available at the ER, the courthouse and by phone.', '$50 trains a peer coach for a day. $750 covers a month of overnight phone support.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000025/logo.png'),
  ('00000000-0000-4000-a000-000000000026', 'little-oak-early-learning', 'Little Oak Early Learning', '00-0000026', 'https://example.org/little-oak-early-learning', 'Sliding-scale preschool so every child starts kindergarten ready, whatever their family earns.', '$60 covers a week of preschool for one child. $1,800 funds a full scholarship for a season.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000026/logo.png'),
  ('00000000-0000-4000-a000-000000000027', 'mobile-dental-neighbors', 'Mobile Dental Neighbors', '00-0000027', 'https://example.org/mobile-dental-neighbors', 'A dental van and volunteer dentists bringing free cleanings and fillings to schools and shelters.', '$75 covers a child''s cleaning and sealants. $3,000 keeps the van running for a month.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000027/logo.png'),
  ('00000000-0000-4000-a000-000000000028', 'prairie-wind-food-bank', 'Prairie Wind Food Bank', '00-0000028', 'https://example.org/prairie-wind-food-bank', 'The regional food bank for twelve rural counties, supplying 90 pantries and school programs.', '$1 helps provide three meals. $100 fills a weekend backpack for a child for a semester.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000028/logo.png'),
  ('00000000-0000-4000-a000-000000000029', 'old-mill-theater', 'Old Mill Community Theater', '00-0000029', 'https://example.org/old-mill-theater', 'Community theater in a restored mill: free youth workshops and pay-what-you-can shows.', '$20 gives a family pay-what-you-can tickets. $500 funds a youth workshop session.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000029/logo.png'),
  ('00000000-0000-4000-a000-000000000030', 'open-gate-youth-shelter', 'Open Gate Youth Shelter', '00-0000030', 'https://example.org/open-gate-youth-shelter', 'A safe place to sleep and a path forward for young people 16 to 24 with nowhere else to go.', '$40 covers a night of shelter and meals. $1,200 funds a month of transitional housing.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000030/logo.png'),
  ('00000000-0000-4000-a000-000000000031', 'hilltop-senior-meals', 'Hilltop Senior Meals', '00-0000031', 'https://example.org/hilltop-senior-meals', 'Hot meals delivered to homebound seniors by volunteers who also stop to talk.', '$8 delivers one hot meal and a visit. $240 covers a month of weekday meals for one senior.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000031/logo.png'),
  ('00000000-0000-4000-a000-000000000032', 'riverbank-cleanup-crew', 'Riverbank Cleanup Crew', '00-0000032', 'https://example.org/riverbank-cleanup-crew', 'Monthly river cleanups and a year-round campaign to keep trash out of storm drains.', '$30 supplies one volunteer with gloves, grabber and bags. $400 funds a storm-drain filter.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000032/logo.png'),
  ('00000000-0000-4000-a000-000000000033', 'seedline-growers', 'Seedline Growers Collective', '00-0000033', 'https://example.org/seedline-growers', 'Farmland, tools and training for refugee and immigrant farmers starting their own businesses.', '$45 buys seed for a quarter-acre. $1,000 helps a farmer start selling at market.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000033/logo.png'),
  ('00000000-0000-4000-a000-000000000034', 'bright-lines-coding', 'Bright Lines Coding Club', '00-0000034', 'https://example.org/bright-lines-coding', 'Free after-school coding clubs for teens, with mentors from local tech jobs.', '$35 covers a student''s club year. $350 refurbishes a laptop to lend.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000034/logo.png'),
  ('00000000-0000-4000-a000-000000000035', 'quiet-hours-hospice', 'Quiet Hours Hospice Volunteers', '00-0000035', 'https://example.org/quiet-hours-hospice', 'Trained volunteers who keep company with people at the end of life, so no one is alone.', '$60 trains a volunteer for one session. $500 funds a month of overnight vigils.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000035/logo.png'),
  ('00000000-0000-4000-a000-000000000036', 'foster-kitten-network', 'Foster Kitten Network', '00-0000036', 'https://example.org/foster-kitten-network', 'Foster homes for kittens too young for the shelter, from bottle-feeding to adoption.', '$15 buys a week of kitten formula. $120 covers vaccines and spay or neuter for one kitten.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000036/logo.png'),
  ('00000000-0000-4000-a000-000000000037', 'kitchen-table-counseling', 'Kitchen Table Counseling', '00-0000037', 'https://example.org/kitchen-table-counseling', 'Sliding-scale counseling with licensed therapists, in person or by video, in five languages.', '$40 covers a counseling session. $2,000 funds a therapist''s supervision for a quarter.', 'verified', 'nonprofit', '00000000-0000-4000-a000-000000000037/logo.png'),
  ('00000000-0000-4000-a000-000000000038', 'bayside-neighbors-fund', 'Bayside Neighbors Fund', '00-0000038', 'https://example.org/bayside-neighbors-fund', 'A community fund pooling neighbors'' gifts for food and housing programs around the bay.', 'Grants of $5,000 to $25,000 to food and housing nonprofits, decided by a neighbor committee.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000038/logo.png'),
  ('00000000-0000-4000-a000-000000000039', 'alder-family-foundation', 'Alder Family Foundation', '00-0000039', 'https://example.org/alder-family-foundation', 'A family foundation funding learning in and out of school, from preschool through high school.', 'Multi-year grants to education and youth programs, usually $10,000 to $60,000 a year.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000039/logo.png'),
  ('00000000-0000-4000-a000-000000000040', 'fernhill-environmental-trust', 'Fernhill Environmental Trust', '00-0000040', 'https://example.org/fernhill-environmental-trust', 'A private trust protecting rivers, wetlands and wildlife in the region.', 'Grants for restoration, wildlife rehabilitation and stewardship, $5,000 to $50,000.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000040/logo.png'),
  ('00000000-0000-4000-a000-000000000041', 'kestrel-youth-fund', 'Kestrel Youth Fund', '00-0000041', 'https://example.org/kestrel-youth-fund', 'Funding young people''s creativity, sports and leadership, with teens on the grants committee.', 'Grants of $2,500 to $20,000; half of the committee is under 20.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000041/logo.png'),
  ('00000000-0000-4000-a000-000000000042', 'bellweather-health-trust', 'Bellweather Health Trust', '00-0000042', 'https://example.org/bellweather-health-trust', 'A health conversion foundation funding care for people who fall through the cracks.', 'Grants for community health, dental care and mental health, $10,000 to $100,000.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000042/logo.png'),
  ('00000000-0000-4000-a000-000000000043', 'lintel-housing-fund', 'Lintel Housing Fund', '00-0000043', 'https://example.org/lintel-housing-fund', 'Funding the groups that keep people housed, from eviction prevention to first apartments.', 'Rapid grants up to $15,000 for housing stability, decided in under a month.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000043/logo.png'),
  ('00000000-0000-4000-a000-000000000044', 'wrenfield-foundation', 'Wrenfield Foundation', '00-0000044', 'https://example.org/wrenfield-foundation', 'A private foundation for literacy, libraries and the arts.', 'Grants for literacy, libraries and community arts, $5,000 to $40,000.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000044/logo.png'),
  ('00000000-0000-4000-a000-000000000045', 'saltwind-community-foundation', 'Saltwind Community Foundation', '00-0000045', 'https://example.org/saltwind-community-foundation', 'The community foundation for the coast: donor funds, scholarships and grants for coastal towns.', 'Competitive grants twice a year, $5,000 to $30,000, for coastal nonprofits.', 'verified', 'foundation', '00000000-0000-4000-a000-000000000045/logo.png');
