insert into posts (org_id, kind, body, created_at) values
  ('00000000-0000-4000-a000-000000000016', 'update', 'Last night''s routes: 19 stops, 4,100 pounds of produce and bread, all delivered by 7 am.', now() - interval '34 hours'),
  ('00000000-0000-4000-a000-000000000016', 'impact_story', 'A bakery that used to throw out 60 loaves a night now fills two pantry shelves. The owner rides along on Fridays.', now() - interval '288 hours'),
  ('00000000-0000-4000-a000-000000000016', 'ask', 'Our second van needs new tires before winter. $900 gets it there.', now() - interval '720 hours'),
  ('00000000-0000-4000-a000-000000000017', 'impact_story', 'A night-shift nurse fell two months behind after surgery. Rent help plus a payment plan kept her family in the apartment they''ve lived in for nine years.', now() - interval '96 hours'),
  ('00000000-0000-4000-a000-000000000017', 'update', 'Free tenant clinic every Wednesday evening at the library, with volunteer attorneys and interpreters.', now() - interval '456 hours'),
  ('00000000-0000-4000-a000-000000000018', 'update', 'Fall session started with 112 students and 96 volunteer tutors. Waitlist is down to 14.', now() - interval '144 hours'),
  ('00000000-0000-4000-a000-000000000018', 'impact_story', 'Elena came in hating fractions. Last week she taught them to the new kid at her table.', now() - interval '528 hours'),
  ('00000000-0000-4000-a000-000000000018', 'ask', 'We need eight more tutors on Thursdays. Two hours a week, training provided.', now() - interval '840 hours'),
  ('00000000-0000-4000-a000-000000000019', 'update', 'Water testing is back: nitrate levels at Mill Creek dropped for the third year running.', now() - interval '72 hours'),
  ('00000000-0000-4000-a000-000000000019', 'update', 'Willow staking day planted 1,800 live stakes along Heron Run in one morning.', now() - interval '672 hours'),
  ('00000000-0000-4000-a000-000000000020', 'impact_story', 'At 61, Walter read a bedtime story to his granddaughter for the first time. He picked the book himself.', now() - interval '120 hours'),
  ('00000000-0000-4000-a000-000000000020', 'update', 'Evening classes are now at three branch libraries, with child care on site.', now() - interval '576 hours'),
  ('00000000-0000-4000-a000-000000000021', 'update', 'Twenty-two guests moved into their own apartments this quarter, the most we''ve ever had.', now() - interval '53 hours'),
  ('00000000-0000-4000-a000-000000000021', 'ask', 'Move-in kits are running low: sheets, towels, pots and a shower curtain make a first night feel like home.', now() - interval '384 hours'),
  ('00000000-0000-4000-a000-000000000022', 'impact_story', 'The osprey found tangled in fishing line in June flew out over the marsh on Saturday. Twelve volunteers cared for her.', now() - interval '168 hours'),
  ('00000000-0000-4000-a000-000000000022', 'update', 'Our hotline takes calls 7 am to 9 pm. Found an injured bird? Keep it in a dark box and call us.', now() - interval '624 hours'),
  ('00000000-0000-4000-a000-000000000023', 'update', 'Spring showcase: 46 students, 3 bands and one very brave first solo.', now() - interval '192 hours'),
  ('00000000-0000-4000-a000-000000000023', 'ask', 'Have a guitar or keyboard in the closet? We''ll repair it and put it in a student''s hands.', now() - interval '504 hours'),
  ('00000000-0000-4000-a000-000000000024', 'impact_story', 'Hamid cooked in Kabul for twenty years. Six weeks after finishing our program he''s a line cook downtown.', now() - interval '84 hours'),
  ('00000000-0000-4000-a000-000000000024', 'update', 'Thursday community dinners are back, pay what you can. This week: Eritrean lentils and injera.', now() - interval '312 hours'),
  ('00000000-0000-4000-a000-000000000025', 'update', 'Our coaches are now at the county ER every night, not just weekends.', now() - interval '216 hours'),
  ('00000000-0000-4000-a000-000000000025', 'impact_story', 'Two years ago a coach sat with Dee in the ER at 3 am. This month Dee finished peer coach training.', now() - interval '744 hours'),
  ('00000000-0000-4000-a000-000000000026', 'update', 'Our new outdoor classroom is open: raised beds, a mud kitchen and a lot of happy noise.', now() - interval '240 hours'),
  ('00000000-0000-4000-a000-000000000026', 'ask', 'We need picture books that look like our families. Wish list on our site.', now() - interval '648 hours'),
  ('00000000-0000-4000-a000-000000000027', 'update', 'This month the van visited six schools and saw 410 kids. For 180 of them it was a first dental visit.', now() - interval '106 hours'),
  ('00000000-0000-4000-a000-000000000027', 'ask', 'We need volunteer hygienists for Saturday shelter visits.', now() - interval '480 hours'),
  ('00000000-0000-4000-a000-000000000028', 'update', 'Harvest season: 14 farms donated 220,000 pounds of sweet corn, squash and apples this month.', now() - interval '139 hours'),
  ('00000000-0000-4000-a000-000000000028', 'update', 'Weekend backpacks now go home with 2,300 kids in 41 schools.', now() - interval '792 hours'),
  ('00000000-0000-4000-a000-000000000029', 'update', 'Opening night of our fall show sold out, and a third of the seats went pay-what-you-can.', now() - interval '158 hours'),
  ('00000000-0000-4000-a000-000000000029', 'ask', 'The costume shop needs sewing machines and a few patient volunteers.', now() - interval '600 hours'),
  ('00000000-0000-4000-a000-000000000030', 'impact_story', 'Marcus arrived with a backpack and a phone with no service. This fall he started community college, in his own room.', now() - interval '67 hours'),
  ('00000000-0000-4000-a000-000000000030', 'update', 'Our drop-in center is now open until 10 pm, with dinner, showers and laundry.', now() - interval '432 hours'),
  ('00000000-0000-4000-a000-000000000031', 'update', 'Our drivers logged 3,900 deliveries this month. Several also fixed a porch light and a leaky faucet.', now() - interval '185 hours'),
  ('00000000-0000-4000-a000-000000000031', 'ask', 'Routes in the north end need drivers. About 90 minutes, any weekday.', now() - interval '552 hours'),
  ('00000000-0000-4000-a000-000000000032', 'update', 'September cleanup: 210 volunteers, 3,400 pounds of trash, two shopping carts and one bowling ball.', now() - interval '264 hours'),
  ('00000000-0000-4000-a000-000000000032', 'update', 'Ten new storm-drain filters are in along Canal Street.', now() - interval '864 hours'),
  ('00000000-0000-4000-a000-000000000033', 'impact_story', 'Grace farmed in Burundi. This season her stand at the Saturday market sold out of amaranth greens every week.', now() - interval '98 hours'),
  ('00000000-0000-4000-a000-000000000033', 'update', 'Our new cold storage room means farmers can sell all week, not just market day.', now() - interval '696 hours'),
  ('00000000-0000-4000-a000-000000000034', 'update', 'Our teens shipped 31 apps at the fall demo night, including a bus-arrival tracker their school now uses.', now() - interval '146 hours'),
  ('00000000-0000-4000-a000-000000000034', 'ask', 'Upgrading your work laptops? We refurbish and lend them to students.', now() - interval '624 hours'),
  ('00000000-0000-4000-a000-000000000035', 'update', 'Our fall volunteer class graduated 26 new companions. Thank you to the families who shared their stories in training.', now() - interval '360 hours'),
  ('00000000-0000-4000-a000-000000000036', 'update', 'Kitten season by the numbers: 412 kittens fostered since April, 389 adopted.', now() - interval '79 hours'),
  ('00000000-0000-4000-a000-000000000036', 'ask', 'Bottle babies need foster homes now. We provide everything and a mentor.', now() - interval '336 hours'),
  ('00000000-0000-4000-a000-000000000037', 'update', 'Our waitlist is down to two weeks, from eight, after three new therapists joined.', now() - interval '221 hours'),
  ('00000000-0000-4000-a000-000000000037', 'update', 'New: free grief groups on Monday evenings.', now() - interval '720 hours'),
  ('00000000-0000-4000-a000-000000000038', 'update', 'Our neighbor committee met with 18 applicants this fall. Decisions go out November 15.', now() - interval '240 hours'),
  ('00000000-0000-4000-a000-000000000039', 'update', 'We''re moving most grants to three-year general operating support. Our grantees asked; we listened.', now() - interval '408 hours'),
  ('00000000-0000-4000-a000-000000000040', 'update', 'Field visit season: we walked 11 restoration sites with grantees this month.', now() - interval '288 hours'),
  ('00000000-0000-4000-a000-000000000041', 'update', 'Our teen committee picked this year''s grants. Their top criterion: programs that let young people lead.', now() - interval '480 hours'),
  ('00000000-0000-4000-a000-000000000042', 'update', 'We visited every grantee in person this year. What we heard most: fund staff, not just programs.', now() - interval '336 hours'),
  ('00000000-0000-4000-a000-000000000043', 'update', 'Rapid housing grants are open year round. Most decisions in under four weeks.', now() - interval '216 hours'),
  ('00000000-0000-4000-a000-000000000044', 'update', 'Every grantee gets a free day of storytelling coaching this year, so they can share their work in their own words.', now() - interval '528 hours'),
  ('00000000-0000-4000-a000-000000000045', 'update', 'Our spring grant cycle funded 26 coastal nonprofits. Fall applications open next week.', now() - interval '384 hours');
